theme { name: "%s", bg: "#0a0a12", accent: "#7c5cff", accent2: "#35e0c2", text: "#f2f2f7", muted: "#8b8ba3" }

scene {
}

exact.\nwidget Picture { // блок: pictu:
widget Picture { // block: picture
  prop src = "" // path to the image: PNG, JPG, GIF, WEBP
  prop radius = 0
  prop opacity = 1
  prop dim = 0 // dimming 0…1
  on draw {
    alpha(opacity)
    if not image(src, 0, 0, w, h, radius) {
      fill("#ffffff10")
      rect(0, 0, w, h, radius)
      fill(theme.muted)
      text("image: src property", w / 2, h / 2, 13, align: "center", maxw: w - 8)
    }
    if dim > 0 {
      fill(with_alpha("#000000", clamp(dim)))
      rect(0, 0, w, h, radius)
    }
  }
}

exact.\nwidget Video { // блок: video:
widget Video { // block: video
  prop src = "" // path to video: MP4, WEBM, MOV... - without sound, in a circle
  prop radius = 0
  prop dim = 0.25 // dimming 0…1
  prop react = 0.4 // 0…1 - brightens on impacts
  on draw {
    if not video(src, 0, 0, w, h, radius) {
      fill("#ffffff0c")
      rect(0, 0, w, h, radius)
      fill(theme.muted)
      text("video: src property", w / 2, h / 2, 13, align: "center", maxw: w - 8)
    }
    let d = clamp(dim - audio.bass * react * 0.4)
    if d > 0 {
      fill(with_alpha("#000000", d))
      rect(0, 0, w, h, radius)
    }
  }
}

exact.\nwidget Blob { // блок: blob\:
widget Blob { // block: blob
  prop color = theme.accent
  prop color2 = theme.accent2
  prop points = 48
  prop wobble = 0.18 // wobble strength
  prop react = 0.6 // 0...1 - swells with bass
  prop speed = 0.6
  on draw {
    let cx = w/2
    let cy = h / 2
    let r = min(w, h) * 0.38 * (1 + audio.bass * react * 0.25)
    let pts = []
    for i in 0..points {
      let a = i * TAU / points
      let n = noise(cos(a) * 1.3 + time * speed, sin(a) * 1.3 + time * speed * 0.7, audio.mid)
      let rr = r * (1 + n * wobble * 2 + audio.fft[i % 64] * react * 0.12)
      push(pts, cx + cos(a) * rr * w / min(w, h), cy + sin(a) * rr * h / min(w, h))
    }
    fill(radial(cx, cy, r * 1.2, [color, color2]))
    curve(pts, true)
  }
}

exact.\nwidget Label { // блок: label:
widget Label { // block: label
  prop label = "Text"
  prop bind = "" // "title" | "artist" | "album" | "time" — substitute track data
  prop size = 28
  prop color = theme.text
  prop align = "left" // left | center | right
  prop weight = 700
  prop font=nil
  on draw {
    let s = label
    if bind == "title" { s = track.loaded ? track.title : "ECHOES" }
    elif bind == "artist" { s = track.artist }
    elif bind == "album" { s = track.album }
    elif bind == "time" { s = fmt_time(track.position) + " / " + fmt_time(track.duration) }
    fill(color)
    let tx = align == "center" ? w/2 : (align == "right" ? w : 0)
    text(s, tx, h / 2, size, align: align, weight: weight, font: font, maxw: w)
  }
}

exact.\nwidget TrackInfo { // блок: title:
