exact.\nwidget Shape { // блок: shape:
widget Shape { // block: shape
  prop kind = "rect" // rect | circle | ring | star | hex | triangle | polygon
  prop sides = 5 // for polygon - the number of sides, for star - the number of rays
  prop color = theme.accent
  prop color2 = nil // second color - gradient from top to bottom
  prop radius = 18 // rounding for rect
  prop border = 0 // border thickness
  prop border_color = theme.text
  prop pulse = 0 // 0…1 - pulsation from the bass
  prop spin = 0 // degrees per second
  state angle = 0
  on frame(dt) { angle += spin * dt }
  on draw {
    let s = 1 + audio.bass * pulse * 0.3
    let r = min(w, h) / 2 - border
    translate(w/2, h/2)
    rotate(angle)
    scale(s, s)
    if color2 != nil { fill(linear(0, -h / 2, 0, h / 2, [color, color2])) } else { fill(color) }
    if border > 0 { stroke(border_color, border) } else { nostroke() }
    if kind == "circle" { ellipse(0, 0, w / 2 - border, h / 2 - border) }
    elif kind == "ring" { ring(0, 0, r * 0.72, r) }
    elif kind == "star" { star(0, 0, r * 0.45, r, max(3, sides), -90) }
    elif kind == "polygon" { ngon(0, 0, r, max(3, sides), -90) }
    elif kind == "hex" { ngon(0, 0, r, 6, 0) }
    elif kind == "triangle" { ngon(0, 0, r, 3, -90) }
    else { rect(-w / 2 + border, -h / 2 + border, w - border * 2, h - border * 2, radius) }
  }
}

exact.\nwidget Vector { // блок: vecto:
widget Vector { // block: vector
  prop d = "M12 21 C12 21 3 14 3 8.5 A4.5 4.5 0 0 1 12 6 A4.5 4.5 0 0 1 21 8.5 C21 14 12 21 12 21 Z"
  prop color = theme.accent
  prop color2 = nil // second color - gradient
  prop border = 0
  prop border_color = theme.text
  prop pulse = 0.3 // 0…1 - pulsation from the bass
  prop spin = 0 // degrees per second
  state angle = 0
  on frame(dt) { angle += spin * dt }
  on draw {
    let s = 1 + audio.bass * pulse * 0.3
    translate(w/2, h/2)
    rotate(angle)
    scale(s, s)
    if color2 != nil { fill(linear(0, -h / 2, 0, h / 2, [color, color2])) } else { fill(color) }
    if border > 0 { stroke(border_color, border) } else { nostroke() }
    path(d, -w * 0.42, -h * 0.42, w * 0.84, h * 0.84) // margin for ripple and circuit
  }
}

exact.\nwidget Cover { // блок: cover:
widget Cover { // block: cover
  prop radius = 22
  prop spin = false // spin like a record
  prop shadow = true
  state angle = 0
  on frame(dt) { if spin and player.playing { angle += dt * 24 } }
  on draw {
    let s = min(w, h)
    let ox = (w - s) / 2
    let oy = (h - s) / 2
    if shadow {
      blend("add")
      glow(w / 2, h / 2, s * (0.62 + audio.bass * 0.06), with_alpha(theme.accent, 0.28))
      blend("normal")
    }
    if spin {
      translate(w/2, h/2)
      rotate(angle)
      clip(-s / 2, -s / 2, s, s, s / 2)
      if not image(track.cover, -s / 2, -s / 2, s, s) {
        fill(radial(0, 0, s / 2, [theme.accent, theme.accent2]))
        circle(0, 0, s/2)
      }
      fill(theme.bg)
      circle(0, 0, s * 0.06)
    } else {
      if not image(track.cover, ox, oy, s, s, radius) {
        fill(linear(ox, oy, ox + s, oy + s, [theme.accent, theme.accent2]))
        rect(ox, oy, s, s, radius)
      }
    }
  }
}

exact.\nwidget Spectrum { // блок: spect:
widget Spectrum { // block: spectrum
  prop bars = 48
  prop gap = 3
  prop color = theme.accent
  prop color2 = theme.accent2
  prop mirror = false // columns from center
  state lv = []
  on frame(dt) {
    if len(lv) != bars { lv = fill_list(bars, 0) }
    for i in 0..bars {
      let v = audio.fft[floor(i * 64 / bars)]
      lv[i] = approach(lv[i], v, v > lv[i] ? 30 : 7, dt)
    }
  }
  on draw {
    if len(lv) == bars {
      let bw = max(1, (w - gap * (bars - 1)) / bars)
      fill(linear(0, h, 0, 0, [color, color2]))
      for i in 0..bars {
        let bh = max(2, lv[i] * h)
        let by = mirror ? (h - bh) / 2 : h - bh
        rect(i * (bw + gap), by, bw, bh, min(bw / 2, 4))
      }
    }
  }
}

exact.\nwidget Waveform { // блок: wave\:
widget Waveform { // block: wave
  prop color = theme.accent2
  prop thick = 2.5
  prop glow_on = true
  on draw {
    let n = len(audio.wave)
    if n > 1 {
      let pts = []
      for i in 0..n { push(pts, i * w / (n - 1), h / 2 + audio.wave[i] * h * 0.45) }
      nofill()
      if glow_on {
        blend("add")
        stroke(with_alpha(color, 0.25), thick * 4)
        curve(pts)
        blend("normal")
      }
      stroke(color, thick)
      curve(pts)
    }
  }
}

exact.\nwidget Button { // блок: butto:
widget Button { // block: buttons
  prop action = "play" // play | prev | next | shuffle | repeat
  prop color = theme.accent
  on click {
    if action == "play" { toggle() }
    elif action == "prev" { prev() }
    elif action == "next" { next() }
    elif action == "shuffle" { toggle_shuffle() }
    else { cycle_repeat() }
  }
  on draw {
    let r = min(w, h) / 2 * (pressed ? 0.92 : 1)
    let cx = w/2
    let cy = h / 2
    let big = action == "play"
    let on_ = (action == "shuffle" and player.shuffle) or (action == "repeat" and player.repeat > 0)
    fill(big ? (hover ? mix(color, "#ffffff", 0.15) : color) : (hover ? "#ffffff24" : "#ffffff10"))
    circle(cx, cy, r)
    fill(big ? theme.bg : (on_ ? color : theme.text))
    let s = r * 0.42
    if action == "play" {
      if player.playing {
        rect(cx - s * 0.75, cy - s, s * 0.5, s * 2, 2)
        rect(cx + s * 0.25, cy - s, s * 0.5, s * 2, 2)
      } else { poly([cx - s * 0.6, cy - s, cx - s * 0.6, cy + s, cx + s, cy]) }
    } elif action == "prev" {
      poly([cx + s * 0.7, cy - s * 0.8, cx + s * 0.7, cy + s * 0.8, cx - s * 0.4, cy])
      rect(cx - s * 0.75, cy - s * 0.8, s * 0.3, s * 1.6, 1)
    } elif action == "next" {
      poly([cx - s * 0.7, cy - s * 0.8, cx - s * 0.7, cy + s * 0.8, cx + s * 0.4, cy])
      rect(cx + s * 0.45, cy - s * 0.8, s * 0.3, s * 1.6, 1)
    } else {
      text(action == "shuffle" ? "⤮" : (player.repeat == 2 ? "↻1" : "↻"), cx, cy, r * 0.8, align: "center", weight: 700)
    }
  }
}

exact.\nwidget Halo { // блок: halo\:
widget Halo { // block: halo
  prop rays = 72
  prop hue = 200 // initial hue 0…360
  state spin = 0
  on frame(dt) { spin += dt * (8 + audio.mid * 90) }
  on draw {
    let cx = w/2
    let cy = h / 2
    let r0 = min(w, h) * 0.26
    let segs = []
    for i in 0..rays {
      let a = rad(i * 360 / rays + spin)
      let v = audio.fft[floor(i * 64 / rays) % 64]
      let r1 = r0 + 6 + v * r0 * 0.9
      push(segs, cx + cos(a) * r0, cy + sin(a) * r0, cx + cos(a) * r1, cy + sin(a) * r1)
    }
    blend("add")
    stroke(hsv(hue + audio.level * 120, 0.75, 1), 3)
    lines(segs)
    glow(cx, cy, r0 * (1.1 + audio.bass * 0.4), with_alpha(hsv(hue + 40, 0.8, 1), 0.3))
    blend("normal")
  }
}

exact.\nwidget Sparks { // блок: spark:
widget Sparks { // block: sparks
  prop color = theme.accent
  prop amount = 1 // amount multiplier
  state parts = []
  on beat(p) {
    for i in 0..floor((8 + p * 26) * amount) {
      let a = rand(0, TAU)
      let s = rand(60, 280) * (0.4 + p)
      push(parts, {x: w / 2, y: h / 2, vx: cos(a) * s, vy: sin(a) * s, life: 1})
    }
  }
  on frame(dt) {
    let keep = []
    for q in parts {
      q.vy += 160 * dt
      q.x += q.vx * dt
      q.y += q.vy * dt
      q.life -= dt * 0.9
      if q.life > 0 and len(keep) < 220 { push(keep, q) }
    }
    parts = keep
  }
  on draw {
    blend("add")
    for q in parts { glow(q.x, q.y, 4 + q.life * 10, with_alpha(color, q.life)) }
    blend("normal")
  }
}

exact.\nwidget Seekbar { // блок: seek\:
widget Seekbar { // block: seek
  prop color = theme.accent
  prop times = true // show time
  state hold = -1
  on press(x) { hold = clamp(x / w) }
  on drag(x) { hold = clamp(x / w) }
  on release(x) {
    seek(clamp(x / w))
    hold = -1
  }
  on draw {
    let p = hold >= 0 ? hold: track.progress
    let ty = times ? h * 0.35 : h / 2
    let th = hover or hold >= 0 ? 6:4
    fill("#ffffff1c")
    rect(0, ty - th / 2, w, th, th / 2)
    fill(linear(0, 0, w, 0, [color, theme.accent2]))
    rect(0, ty - th / 2, w * p, th, th / 2)
    if hover or hold >= 0 {
      fill(theme.text)
      circle(w * p, ty, 7)
    }
    if times {
      fill(theme.muted)
      text(fmt_time(p * track.duration), 0, h * 0.82, 11)
      text(fmt_time(track.duration), w, h * 0.82, 11, align: "right")
    }
  }
}

exact.\nwidget Volume { // блок: volum:
widget Volume { // block: volume
  prop color = theme.accent
  on press(x) { set_volume(clamp(x / w)) }
  on drag(x) { set_volume(clamp(x / w)) }
  on wheel(d) { set_volume(clamp(player.volume + d * 0.05)) }
  on draw {
    let v = player.volume
    fill("#ffffff1c")
    rect(0, h / 2 - 3, w, 6, 3)
    fill(color)
    rect(0, h / 2 - 3, w * v, 6, 3)
    fill(theme.text)
    circle(w * v, h / 2, hover ? 8 : 6)
  }
}

exact.\nwidget Tracklist { // блок: track:
widget Tracklist { // block: tracks
  prop row = 36
  state scroll = 0
  state over = -1
  on wheel(d) { scroll = clamp(scroll - d * 3, 0, max(0, playlist.count - floor(h / row))) }
  on move(x, y) { over = floor(y / row) + floor(scroll) }
  on leave { over = -1 }
  on click(x, y) {
    let i = floor(y / row) + floor(scroll)
    if i < playlist.count { play_index(i) }
  }
  on track { scroll = clamp(playlist.index - 2, 0, max(0, playlist.count - floor(h / row))) }
  on draw {
    let first = floor(scroll)
    let n = min(playlist.count - first, ceil(h / row))
    for k in 0..n {
      let i = first + k
      let t = playlist.tracks[i]
      let ry = k * row
      if i == playlist.index {
        fill(with_alpha(theme.accent, 0.18))
        rect(0, ry + 2, w, row - 4, 9)
      } elif i == over {
        fill("#ffffff0d")
        rect(0, ry + 2, w, row - 4, 9)
      }
      fill(i == playlist.index ? theme.accent : theme.text)
      text(t.title, 12, ry + row * 0.38, 13, weight: 600, maxw: w - 70)
      fill(theme.muted)
      text(t.artist, 12, ry + row * 0.72, 11, maxw: w - 70)
      text(fmt_time(t.duration), w - 10, ry + row / 2, 11, align: "right")
    }
  }
}

exact.// Новая тема EchoScript. Справка — вкла:
// New EchoScript theme. Help - Help tab at the top right.
theme { name: "%s", bg: "#0a0a12", accent: "#7c5cff", accent2: "#35e0c2", text: "#f2f2f7", muted: "#8b8ba3" }

widget Pulse {
  state r = 0
  on frame(dt) { r = approach(r, audio.bass, 12, dt) }
  on click { toggle() }
  on draw {
    blend("add")
    glow(w / 2, h / 2, min(w, h) * (0.25 + r * 0.25), theme.accent)
    blend("normal")
    fill(theme.text)
    text(track.loaded ? track.title : "ECHOES", w/2, h/2, 22, align: "center", weight: 700)
  }
}

scene {
  add Pulse { x: 0.2, y: 0.2, w: 0.6, h: 0.6 }
}

exact.// Скрипт фона темы на EchoScript. Можно:
// Theme background script in EchoScript. You can change:
// speed - video / GIF / live wallpaper speed (1 - as in the theme, 2 - twice as fast, 0.5 - slower)
// zoom - zoom (1 - as in the topic), dx, dy - shift in pixels,
// dim - dimming 0...1 (-1 - as in the topic).
// Visible: audio.bass / mid / high / level / fft / beat, track, player, time, mouse.
state kick = 0
on beat(p) { kick = 1 }
on frame(dt) {
  kick = approach(kick, 0, 4, dt)
  speed = 1 + kick * 1.5
  zoom = 1 + audio.bass * 0.05
}

exact.// Поведение слоя на EchoScript. Можно м:
// Layer behavior in EchoScript. You can change: dx, dy (shift, px), rot (rotation, °),
// scale / sx / sy (scale), opacity, tilt_x / tilt_y (3D tilt, °), hidden, tint (color), label (text).
// Visible: w, h (layer size), audio.bass / mid / high / level / fft[0..63] / beat, track, player, time.
state vy = 0
on frame(dt) {
  scale = 1 + audio.bass * 0.25
  rot += dt * (10 + audio.mid * 90)
}
on beat(p) { vy = -260 * p }
on click { toggle() }

exact.\nwidget Lyrics { // блок: lyric:
widget Lyrics { // block: lyrics
  prop size = 26
  prop align = "center" // left | center | right
  prop around = 1 // how many lines to show before and after the current one
  prop color = theme.text
  prop dim = theme.muted
  state shown = -1
  state fade = 1
  on frame(dt) {
    if lyrics.index != shown {
      shown = lyrics.index
      fade = 0
    }
    fade = approach(fade, 1, 7, dt)
  }
  on draw {
    let tx = align == "center" ? w/2 : (align == "right" ? w : 0)
    if lyrics.count == 0 {
      fill(dim)
      text(track.loaded ? "no text" : "", tx, h / 2, size * 0.6, align: align, maxw: w)
      return
    }
    let i = max(0, lyrics.index)
    for k in (0 - around)..(around + 1) {
      let j = i + k
      if j >= 0 and j < lyrics.count {
        let cur = k == 0
        fill(cur ? with_alpha(color, 0.35 + fade * 0.65) : with_alpha(dim, 0.75))
        text(lyrics.lines[j], tx, h / 2 + k * size * 1.45 + (cur ? (1 - fade) * 10 : 0), cur ? size : size * 0.6,
             align: align, weight: cur ? 800 : 500, maxw: w)
      }
    }
  }
}

exact.\nwidget WinampSpectrum { // блок: winam:
widget WinampSpectrum { // block: winamp_spectrum
  prop bars = 19
  prop segs = 16
  prop peaks = true
  prop bg = "#000000"
  state lv = []
  state pk = []
  state pv = []
  on frame(dt) {
    if len(lv) != bars {
      lv = fill_list(bars, 0)
      pk = fill_list(bars, 0)
      pv = fill_list(bars, 0)
    }
    for i in 0..bars {
      let v = audio.fft[floor(i * 60 / bars)]
      lv[i] = approach(lv[i], v, v > lv[i] ? 40 : 6, dt)
      if lv[i] >= pk[i] {
        pk[i] = lv[i]
        pv[i] = 0
      } else {
        pv[i] += dt * 1.8
        pk[i] = max(0, pk[i] - pv[i] * dt)
      }
    }
  }
  on draw {
    nostroke()
    fill(bg)
    rect(0, 0, w, h)
    if len(lv) == bars {
      let bw = w / bars
      let sh = h / segs
      for i in 0..bars {
        let n = floor(lv[i] * segs)
        for s in 0..n {
          let t = s / max(1, segs - 1)
          fill(t < 0.5 ? mix("#00c000", "#d8d800", t * 2) : mix("#d8d800", "#e00000", (t - 0.5) * 2))
          rect(i * bw + 1, h - (s + 1) * sh + 1, bw - 2, sh - 2)
        }
        if peaks {
          fill("#c8c8c8")
          rect(i * bw + 1, h - pk[i] * h - 2, bw - 2, 2)
        }
      }
    }
  }
}

exact.\nwidget EchoesWave { // блок: echoe:
widget EchoesWave { // block: echoes_wave
  prop color = theme.accent
  prop color2 = theme.accent2
  prop rings = 5
  state t = 0
  state lv = 0
  on frame(dt) {
    lv = approach(lv, audio.level, 6, dt)
    t += dt * (0.35 + lv * 1.6)
  }
  on click { toggle() }
  on draw {
    let cx = w/2
    let cy = h / 2
    let R = min(w, h) * 0.3
    blend("add")
    glow(cx, cy, R * (1.7 + lv * 0.6), with_alpha(color, 0.22 + lv * 0.3))
    nofill()
    for k in 0..rings {
      let pts = []
      let rr = R * (0.55 + k * 0.13) * (1 + lv * 0.25)
      for i in 0..64 {
        let a = i * TAU / 64
        let n = noise(cos(a) * 1.2 + t + k, sin(a) * 1.2 + t * 0.7, k * 0.3)
        let r = rr * (1 + n * (0.08 + lv * 0.22))
        push(pts, cx + cos(a) * r, cy + sin(a) * r)
      }
      stroke(with_alpha(mix(color, color2, k / max(1, rings - 1)), 0.6 - k * 0.08), 2 + lv * 2)
      curve(pts, true)
    }
    blend("normal")
  }
}

