QFrame#Panel {{ background: transparent; border: none; }}
QFrame#SubPanel {{ background: {4}; border: none; border-radius: 20px; }}
QFrame#CenterStage {{ background: transparent; border: none; }}
/* Transport - cream “menu strip”, rests on the poster */
QFrame#DockCard {{ background: {5}; border: none; border-radius: 30px; }}

/* ── Typography ── */
QLabel#Title {{ font-size: 26px; font-weight: 900; color: {6};
                background: transparent; padding: 0px 2px; }}
QLabel#Artist {{ font-size: 12px; font-weight: 600; color: {7};
                background: transparent; padding: 0px 2px; }}
QLabel#Section {{ font-size: 14px; font-weight: 900; color: {8}; }}
QLabel#Big {{ font-size: 14px; font-weight: 900; color: {9}; }}
QLabel#Sub {{ font-size: 10px; color: {10}; }}
QLabel#Time {{ font-size: 10px; font-weight: 700; color: {11}; }}

/* ── Buttons: cream tablets ──
   radius ≤ half the height of the lowest button (~28 px), otherwise Qt draws right angles */
QPushButton {{ background: {12}; color: {13}; border: none;
              border-radius: 13px; padding: 8px 16px; font-weight: 700; }}
QPushButton:hover {{ color: {14}; background: {15}; }}
QPushButton:pressed {{ background: {16}; color: {17}; }}
QPushButton:checked {{ background: {18}; color: {19}; }}

QPushButton#PlayBtn {{ background: {20}; border: none; border-radius: 26px;
                      min-width: 72px; max-width: 72px; min-height: 52px; max-height: 52px; }}
QPushButton#PlayBtn:hover {{ background: {21}; }}
QPushButton#PlayBtn:pressed {{ background: {22}; }}

QPushButton#IconBtn {{ background: transparent; color: {23}; border: none;
                      border-radius: 16px; min-width: 58px; max-width: 76px;
                      min-height: 34px; max-height: 34px; padding: 0 10px;
                      font-size: 11px; font-weight: 800; }}
QPushButton#IconBtn:hover {{ background: {24}; }}
QPushButton#IconBtn:checked {{ background: {25}; color: {26}; }}

/* Large text in the traffic lane: “prev / next / repeat” */
QPushButton#IconBtn[fluidBig="true"] {{ background: transparent; color: {27};
                      font-size: 16px; font-weight: 900; border-radius: 18px;
                      min-width: 40px; max-width: 160px; min-height: 40px; max-height: 40px;
                      padding: 0 12px; }}
QPushButton#IconBtn[fluidBig="true"]:hover {{ background: {28}; color: {29}; }}
QPushButton#IconBtn[fluidBig="true"]:checked {{ background: {30}; color: {31}; }}

/* Main menu items: huge orange line text */
QPushButton#GhostBtn[fluidMenu="true"] {{ background: transparent; color: {32}; border: none;
                      font-size: 30px; font-weight: 900; text-align: left;
                      padding: 2px 18px; border-radius: 22px;
                      min-width: 0px; }}
QPushButton#GhostBtn[fluidMenu="true"]:hover {{ background: {33}; color: {34}; }}
QPushButton#GhostBtn[fluidMenu="true"]:checked {{ background: {35}; color: {36}; }}

QPushButton#AccentBtn {{ background: {37}; color: {38}; border: none;
                        border-radius: 13px; font-weight: 900; }}
QPushButton#AccentBtn:hover {{ background: {39}; color: {40}; }}
QPushButton#GhostBtn {{ background: transparent; color: {41};
                       border: 2px solid {42}; border-radius: 13px;
                       padding: 6px 14px; font-weight: 700; }}
QPushButton#GhostBtn:hover {{ border-color: {43}; color: {44}; }}
QPushButton#GhostBtn:checked {{ background: {45}; border-color: {46}; color: {47}; }}

/* ── Sliders: progress is colored with the dominant color of the cover ── */
QSlider::groove:horizontal {{ height: 6px; background: {48}; border-radius: 3px; }}
QSlider::sub-page:horizontal {{ background: {49}; border-radius: 3px; }}
QSlider::handle:horizontal {{ width: 14px; height: 14px; margin: -4px 0;
                             background: {50}; border-radius: 7px; }}
QSlider::groove:vertical {{ width: 6px; background: {51}; border-radius: 3px; }}
QSlider::sub-page:vertical {{ background: {52}; border-radius: 3px; }}
QSlider::handle:vertical {{ width: 14px; height: 14px; margin: 0 -4px;
                           background: {53}; border-radius: 7px; }}

/* ── Lists: cream dies on beige ── */
QListWidget {{ background: {54}; border: none; border-radius: 22px;
              outline: none; color: {55}; padding: 6px; }}
QListWidget::item {{ padding: 8px 10px; margin: 1px 0px; border-radius: 16px; min-height: 36px; }}
QListWidget::item:hover {{ background: {56}; }}
QListWidget::item:selected {{ background: {57}; color: {58}; font-weight: 800; }}

/* ── Input fields ── */
QLineEdit, QTextEdit, QPlainTextEdit {{ background: {59}; color: {60}; border: none;
                   border-radius: 14px; padding: 8px 14px; selection-background-color: {61}; }}
QTextEdit, QPlainTextEdit {{ border-radius: 22px; padding: 14px; }}
QLineEdit:focus {{ border: 2px solid {62}; }}
QComboBox, QSpinBox {{ background: {63}; color: {64}; border: none;
                      border-radius: 14px; padding: 8px 14px; font-weight: 700; }}
QComboBox::drop-down {{ border: none; width: 24px; }}
QComboBox QAbstractItemView {{ background: {65}; color: {66}; border: 1px solid {67};
                              border-radius: 14px; selection-background-color: {68};
                              selection-color: {69}; padding: 4px; }}

QCheckBox {{ color: {70}; spacing: 10px; font-weight: 700; }}
QCheckBox::indicator {{ width: 18px; height: 18px; border-radius: 9px;
                       border: 2px solid {71}; background: {72}; }}
QCheckBox::indicator:checked {{ background: {73}; border-color: {74}; }}

QProgressBar {{ background: {75}; border: none; border-radius: 8px; height: 14px;
               text-align: center; color: {76}; }}
QProgressBar::chunk {{ background: {77}; border-radius: 8px; }}

QTabWidget::pane {{ border: none; background: transparent; }}
QTabBar::tab {{ background: transparent; color: {78}; padding: 7px 18px;
               border-radius: 14px; margin: 2px; font-weight: 800; }}
QTabBar::tab:selected {{ background: {79}; color: {80}; }}
QTabBar::tab:hover {{ color: {81}; }}

QScrollBar:vertical {{ background: transparent; width: 6px; margin: 0; }}
QScrollBar::handle:vertical {{ background: {82}; border-radius: 3px; min-height: 28px; }}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {{ height: 0; }}
QScrollBar:horizontal {{ height: 0; }}

QDialog {{ background: {83}; }}
QMenu {{ background: {84}; color: {85}; border: 1px solid {86}; border-radius: 12px; padding: 6px; }}
QMenu::item {{ padding: 6px 18px; border-radius: 8px; }}
QMenu::item:selected {{ background: {87}; color: {88}; }}
QToolTip {{ background: {89}; color: {90}; border: 1px solid {91}; padding: 4px 8px; }}

